int main() {
    while (scanf("%d %d", &D, &N), D | N) {
        for (int i = 0; i < N; i++) scanf("%d %d %d", &a[i], &e[i], &r[i]);

        int maxr = *max_element(r, r + N);
        fill(&dp[0][0], &dp[0][0] + sizeof(dp) / sizeof(dp[0][0]), 999999999); // Simplified fill

        dp[0][0] = 0;

        for (int i = 0; i < D; i++) {
            for (int j = 0; j <= maxr; j++) {
                if (dp[i][j] == 999999999) continue; // Skip irrelevant states
                for (int k = 0; k < N; k++) {
                    if (j >= r[k]) { // Check if we can use the current item
                        int p = min(j + e[k], maxr), q = min(i + a[k], D);
                        dp[q][p] = min(dp[q][p], dp[i][j] + 1);
                    }
                }
            }
        }

        int ret = *min_element(dp[D], dp[D] + maxr + 1);
        if (ret == 999999999) printf("NA\n");
        else printf("%d\n", ret);
    }
}

